import {adaptivePoints,pointSegmentDistance} from './bezier.js';
import {orderedObjects} from './layers.js';
import {fallRegions} from './fall-regions.js';
import {worldPath,samples,parsePath,point,inverse,evaluatedPath,polyD} from './core.js';
import {effectParts,modifierParts} from './effects.js';
import {visible,locked,isolationIds} from './model.js';
const cache=new Map();
function inside(p,ring){let v=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)v=!v;}return v;}
const distance=pointSegmentDistance;
function contoursOf(path){return [path,...path.subpaths||[]].map(p=>({points:adaptivePoints(p,.12),closed:p.closed}));}
export function hitGeometry(o,os){const source=os.find(s=>s.id===o.source),key=JSON.stringify([o,source]);if(cache.has(key))return cache.get(key);let parts=[];if(o.type==='path'){const p=worldPath(o);if(o.construction)parts.push(...effectParts(o.construction,o).map(p=>({...p,contours:contoursOf(parsePath(p.d))})));else parts.push({contours:contoursOf(p),fill:o.gradient?'#000000':o.fill,width:o.width*Math.max(Math.hypot(o.matrix[0],o.matrix[1]),Math.hypot(o.matrix[2],o.matrix[3])),stroke:o.stroke});parts.push(...fallContourParts(o));parts.push(...modifierParts(o).map(p=>({...p,contours:contoursOf(parsePath(p.d))})));}else if(source)parts=effectParts(o,source).map(p=>({...p,contours:contoursOf(parsePath(p.d))}));if(cache.size>400)cache.clear();cache.set(key,parts);return parts;}
function partHit(part,p,tolerance){let filled=false;if(part.fill&&part.fill!=='none')for(const c of part.contours)if(c.closed&&inside(p,c.points))filled=!filled;if(filled)return true;if(part.stroke==='none'||part.width===0)return false;for(const c of part.contours)for(let i=1;i<c.points.length;i++)if(distance(p,c.points[i-1],c.points[i])<=tolerance+(part.width||0)/2)return true;return false;}
export function hitDetail(o,os,p,tolerance=5){if(!o)return null;if(o.type==='image'||o.type==='text'){if(o.matrix[0]*o.matrix[3]-o.matrix[1]*o.matrix[2]===0)return null;const q=point(inverse(o.matrix),p);return q.x>=0&&q.y>=0&&q.x<=o.w&&q.y<=o.h?{id:o.id,ownerId:o.id}:null;}const parts=hitGeometry(o,os);for(const part of [...parts].reverse())if(partHit(part,p,tolerance))return {id:o.id,ownerId:o.id,modifierId:part.ownerModifier||null,generated:!!part.ownerId};return null;}
export function hitObject(o,os,p,tolerance=5){return !!hitDetail(o,os,p,tolerance);}
export function paintOrder(os){return os.filter(o=>o.semanticType!=='region').flatMap(o=>[o,...(o.regionIds||[]).map(id=>os.find(r=>r.id===id)).filter(Boolean)]);}
export function clipContains(o,p){return !!o?.nodes&&partHit({contours:contoursOf(worldPath(o)),fill:'#000000',stroke:'none',width:0},p,0);}
export function selectionHits(project,view,p,zoom=1,scope=null){const os=project.views[view],allowed=isolationIds(project,view,scope);return paintOrder(orderedObjects(project,view)).reverse().filter(o=>visible(project,view,o)&&!locked(project,view,o)&&(!allowed||allowed.has(o.id))&&(!o.clip||clipContains(os.find(s=>s.id===o.clip),p))).map(o=>hitDetail(o,os,p,5/zoom)).filter(Boolean);}

export function hitCandidates(...args){return selectionHits(...args).map(h=>h.ownerId);}
export function cycleHit(ids,current,cycle){if(!ids.length)return null;if(!cycle)return ids[0];return ids[(ids.indexOf(current)+1)%ids.length];}

export function constructionHits(project,view,p,zoom=1,scope=null){const os=project.views[view],allowed=isolationIds(project,view,scope),result=[];for(const o of [...os].reverse()){if(!visible(project,view,o)||locked(project,view,o)||allowed&&!allowed.has(o.id)||o.clip&&!hitObject(os.find(s=>s.id===o.clip),os,p,0))continue;for(const part of [...hitGeometry(o,os)].reverse())if((o.source||o.construction||part.ownerModifier)&&partHit(part,p,4/zoom)){result.push({ownerId:o.id,modifierId:part.ownerModifier||null,generated:true});break;}}return result;}

function fallContourParts(o){const result=[];for(const m of o.modifiers?.filter(m=>m.type==='fabricFall'&&m.enabled!==false)||[]){const regions=fallRegions(o,m),local=samples(evaluatedPath(o),32);let run=[];const flush=()=>{if(run.length>1){const d=polyD(run.map(p=>point(o.matrix,p)));result.push({d,stroke:o.stroke,width:o.width,fill:'none',ownerId:o.id,ownerModifier:m.id,contours:contoursOf(parsePath(d))});}run=[];};for(const p of local){const targeted=regions.some(r=>{const x=p.x-r.a.x,y=p.y-r.a.y,u=x*r.tx+y*r.ty,v=x*r.nx+y*r.ny;return v>=-.1&&v<=r.extent+.1&&u>=-20&&u<=r.size+20;});if(targeted)run.push(p);else flush();}flush();}return result;}

export function visibleBounds(o,os){const parts=hitGeometry(o,os),points=parts.flatMap(p=>p.contours.flatMap(c=>c.points));if(!points.length){if(o.type==='image'||o.type==='text'){const m=o.matrix,ps=[{x:0,y:0},{x:o.w,y:0},{x:0,y:o.h},{x:o.w,y:o.h}].map(p=>point(m,p));points.push(...ps);}else return null;}const x=Math.min(...points.map(p=>p.x)),y=Math.min(...points.map(p=>p.y));return {x,y,w:Math.max(...points.map(p=>p.x))-x,h:Math.max(...points.map(p=>p.y))-y};}
export function selectionBounds(os,all){const bs=os.filter(o=>!o.hidden).map(o=>visibleBounds(o,all)).filter(Boolean);if(!bs.length)return null;const x=Math.min(...bs.map(b=>b.x)),y=Math.min(...bs.map(b=>b.y));return {x,y,w:Math.max(...bs.map(b=>b.x+b.w))-x,h:Math.max(...bs.map(b=>b.y+b.h))-y};}
export function marqueeHits(project,view,rect,scope=null){const os=project.views[view],allowed=isolationIds(project,view,scope),corners=[{x:rect.x,y:rect.y},{x:rect.x+rect.w,y:rect.y},{x:rect.x+rect.w,y:rect.y+rect.h},{x:rect.x,y:rect.y+rect.h}],within=p=>p.x>=rect.x&&p.x<=rect.x+rect.w&&p.y>=rect.y&&p.y<=rect.y+rect.h;
const segmentRect=(a,b)=>{let t0=0,t1=1;for(const [p,q]of [[a.x-b.x,a.x-rect.x],[b.x-a.x,rect.x+rect.w-a.x],[a.y-b.y,a.y-rect.y],[b.y-a.y,rect.y+rect.h-a.y]]){if(!p){if(q<0)return false;continue;}const r=q/p;if(p<0)t0=Math.max(t0,r);else t1=Math.min(t1,r);if(t0>t1)return false;}return true;};return os.filter(o=>!o.panelCuts?.length&&visible(project,view,o)&&!locked(project,view,o)&&(!allowed||allowed.has(o.id))).filter(o=>{const b=visibleBounds(o,os);if(!b||b.x>rect.x+rect.w||b.y>rect.y+rect.h||b.x+b.w<rect.x||b.y+b.h<rect.y)return false;if(o.type==='image'||o.type==='text')return true;return corners.some(p=>hitObject(o,os,p,0))||hitGeometry(o,os).some(part=>part.contours.some(c=>c.points.some(within)||c.points.slice(1).some((p,i)=>segmentRect(c.points[i],p))));}).map(o=>o.id);}
